INSERT INTO "Subtitle" ("id", "videoId", "index", "startTime", "endTime", "speaker", "text", "ipa") VALUES
('cf6604567771e4e5e58092e71', 'cmwlxjpfl0000eg5qnideikjk', 1, 0.8, 4, 'Nicole', 'Gumball, don''t forget to take that DVD back today or we''ll get a fine.', '/ˈɡʌmˌbɔːl, doʊnt fərˈɡɛt tə teɪk ðæt ˌdiːˌviːˈdiː bæk təˈdeɪ ɔːr wil ɡɛt ə faɪn/'),
('c6ad7adcd9c017a32bde2bc99', 'cmwlxjpfl0000eg5qnideikjk', 2, 4.1, 6.3, 'Gumball', 'Can''t you do it? You''re the one with the car.', '/kænt juː duː ɪt? jʊr ðə wʌn wɪð ðə kɑːr/'),
('cda57c5e813b624b13d94ccbd', 'cmwlxjpfl0000eg5qnideikjk', 3, 6.8, 10.1, 'Nicole', 'I wasn''t the one who watched Alligators on a Train 72 times.', '/aɪ ˈwʌzənt ðə wʌn huː wɑːtʃt ˈælɪˌɡeɪtərz ɑːn ə treɪn ˈsɛvənti tuː taɪmz/'),
('c95b6991d5c096af833777203', 'cmwlxjpfl0000eg5qnideikjk', 4, 10.3, 13, 'Gumball', 'Uh, but technically, you rented it with your money.', '/ʌ, bət ˈtɛknɪkli, juː ˈrɛntɪd ɪt wɪð jɔːr ˈmʌni/'),
('c59c09e183240450e05a5ee30', 'cmwlxjpfl0000eg5qnideikjk', 5, 13.2, 15.6, 'Nicole', 'The money I have to go and earn to feed you kids!', '/ðə ˈmʌni aɪ hæv tə ɡoʊ ənd ɜːrn tə fiːd juː kɪdz!/'),
('c8eab34bb219f1bd772df088f', 'cmwlxjpfl0000eg5qnideikjk', 6, 15.7, 17.5, 'Gumball', 'The kids you decided to have!', '/ðə kɪdz juː dɪˈsaɪdɪd tə hæv!/'),
('c97eec9d35ceabbf52dfd4897', 'cmwlxjpfl0000eg5qnideikjk', 7, 20.8, 22.7, 'Gumball', 'Yep, no problem, Mom, I''ll take it back.', '/jɛp, noʊ ˈprɑːbləm, mɑːm, aɪl teɪk ɪt bæk/'),
('c253681866a6d0f0685c9d897', 'cmwlxjpfl0000eg5qnideikjk', 8, 22.8, 26.1, 'Nicole', 'Oh, very kind of you, honey. And don''t forget to put on some pants. Bye-bye!', '/oʊ, ˈvɛri kaɪnd əv juː, ˈhʌni. ənd doʊnt fərˈɡɛt tə pʊt ɑːn səm pænts. baɪ baɪ!/'),
('c81b912af5a74795299234893', 'cmwlxjpfl0000eg5qnideikjk', 9, 28.8, 31.8, 'Gumball', 'Darwin, have you seen that DVD anywhere? I—', '/ˈdɑːrwɪn, hæv juː siːn ðæt ˌdiːˌviːˈdiː ˈɛniˌwɛr? aɪ—/'),
('c5632bdcf225d6aab0f4418ea', 'cmwlxjpfl0000eg5qnideikjk', 10, 32, 34, 'Gumball', 'Darwin! What are you doing?!', '/ˈdɑːrwɪn! wʌt ɑːr juː ˈduːɪŋ?!/'),
('c454cf73ff7adb3d1dd8aa281', 'cmwlxjpfl0000eg5qnideikjk', 11, 34.2, 35.8, 'Darwin', 'I''m using the pizza cutter.', '/aɪm ˈjuːzɪŋ ðə ˈpiːtsə ˈkʌtər/'),
('c673502d96fcf23ea51dccd23', 'cmwlxjpfl0000eg5qnideikjk', 12, 36.1, 39.8, 'Gumball', 'That''s not the pizza cutter, that''s the DVD! Oh, give me that!', '/ðæts nɑːt ðə ˈpiːtsə ˈkʌtər, ðæts ðə ˌdiːˌviːˈdiː! oʊ, ɡɪv miː ðæt!/'),
('c771c0fd26f9601322339840d', 'cmwlxjpfl0000eg5qnideikjk', 13, 40.4, 42.6, 'Gumball', 'Aw, man. You really have to be careful with these things.', '/ɔː, mæn. juː ˈrɪəli hæv tə biː ˈkɛrfəl wɪð ðiːz θɪŋz/'),
('cbf8b256a4b5614b652fc6d84', 'cmwlxjpfl0000eg5qnideikjk', 14, 43.1, 45.7, 'Gumball', 'The slightest scratch, and they''re ruined. Forever.', '/ðə ˈslaɪtɪst skrætʃ, ənd ðɛr ˈruːɪnd. fərˈɛvər/'),
('c958e0487584e81dd6380f4fa', 'cmwlxjpfl0000eg5qnideikjk', 15, 46.4, 47.3, 'Darwin', 'Uh, Gumball?', '/ʌ, ˈɡʌmˌbɔːl?/'),
('c0d77e5f6fd90f3658421bcc7', 'cmwlxjpfl0000eg5qnideikjk', 16, 47.4, 50, 'Gumball', 'Uh-bup-bup. I am fed up with your carelessness, Darwin.', '/ʌ-bʌp-bʌp. aɪ æm fɛd ʌp wɪð jɔːr ˈkɛrləsnəs, ˈdɑːrwɪn/'),
('ccf5ca1b33b118c97ab8c179a', 'cmwlxjpfl0000eg5qnideikjk', 17, 50.4, 52.8, 'Gumball', 'This disc utilizes laser technology!', '/ðɪs dɪsk ˈjuːtəˌlaɪzɪz ˈleɪzər tɛkˈnɑːlədʒi!/'),
('c1bcbdbe876b194b658b59017', 'cmwlxjpfl0000eg5qnideikjk', 18, 53.3, 55.1, 'Gumball', 'You have to treat it with respect.', '/juː hæv tə triːt ɪt wɪð rɪˈspɛkt/'),
('cecd3231d3340c17800231aad', 'cmwlxjpfl0000eg5qnideikjk', 19, 55.4, 57.8, 'Darwin', 'You''re using the wrong side of the scrubby sponge.', '/jʊr ˈjuːzɪŋ ðə rɔːŋ saɪd əv ðə ˈskrʌbi spʌndʒ/'),
('c5e8877c55f59c2e006fb3e9f', 'cmwlxjpfl0000eg5qnideikjk', 20, 63.4, 65.5, 'Gumball & Darwin', 'No! No!', '/noʊ! noʊ!/'),
('c30b8db64a9bcd790d7f9d068', 'cmwlxjpfl0000eg5qnideikjk', 21, 66, 67.8, 'Gumball', 'What are we going to do?!', '/wʌt ɑːr wiː ˈɡoʊɪŋ tə duː?!/'),
('cd0c81e6817ee0b1c76b4b5d9', 'cmwlxjpfl0000eg5qnideikjk', 22, 68.2, 70.8, 'Darwin', 'Face the consequences of our actions and tell Mom?', '/feɪs ðə ˈkɑːnsəˌkwɛnsɪz əv ɑːr ˈækʃənz ənd tɛl mɑːm?/'),
('cd4546c18ea0d0d500c8287b7', 'cmwlxjpfl0000eg5qnideikjk', 23, 71, 73.1, 'Gumball', 'Don''t be silly. I''ve got a much better idea.', '/doʊnt biː ˈsɪli. aɪv ɡɑːt ə mʌtʃ ˈbɛtər aɪˈdiːə/'),
('c06201b7569e2ca2630bb46d5', 'cmwlxjpfl0000eg5qnideikjk', 24, 75.1, 75.9, 'Gumball', 'There.', '/ðɛr/'),
('c9196d03d81d4bee00b614d38', 'cmwlxjpfl0000eg5qnideikjk', 25, 76.1, 79.1, 'Gumball', 'You can make anything with cardboard and no one will notice the difference.', '/juː kən meɪk ˈɛniˌθɪŋ wɪð ˈkɑːrdˌbɔːrd ənd noʊ wʌn wɪl ˈnoʊtɪs ðə ˈdɪfərəns/'),
('cc8aa9744e833ac0033ab8e73', 'cmwlxjpfl0000eg5qnideikjk', 26, 79.3, 81.6, 'Darwin', 'Really? It looks kind of obvious.', '/ˈrɪəli? ɪt lʊks kaɪnd əv ˈɑːbviəs/'),
('c5af79a74bddeae13d93457a4', 'cmwlxjpfl0000eg5qnideikjk', 27, 82.2, 86.4, 'Gumball', 'You say that, but I lost my trousers three weeks ago, and still no one''s noticed.', '/juː seɪ ðæt, bət aɪ lɔːst maɪ ˈtraʊzərz θriː wiːks əˈɡoʊ, ənd stɪl noʊ wʌnz ˈnoʊtɪst/'),
('c8d1c59b37b8f1228f086ed61', 'cmwlxjpfl0000eg5qnideikjk', 28, 88, 90.1, 'Darwin', 'Everyone''s noticed how you walk, though.', '/ˈɛvriˌwʌnz ˈnoʊtɪst haʊ juː wɔːk, ðoʊ/'),
('c22f90205e106250e83da7121', 'cmwlxjpfl0000eg5qnideikjk', 29, 90.3, 91, 'Gumball', 'Really?', '/ˈrɪəli?/'),
('c5d752e83044178f187803747', 'cmwlxjpfl0000eg5qnideikjk', 30, 91.2, 93.4, 'Darwin', 'You look like you went to the bathroom in a spacesuit.', '/juː lʊk laɪk juː wɛnt tə ðə ˈbæθˌruːm ɪn ə ˈspeɪsˌsuːt/'),
('cc789b27d6e43d12b6213e0fa', 'cmwlxjpfl0000eg5qnideikjk', 31, 96.6, 98.4, 'Darwin', 'Dude! It''s a letter from Laser Video!', '/duːd! ɪts ə ˈlɛtər frəm ˈleɪzər ˈvɪdioʊ!/'),
('c9385accb1166f5bdb11ceb02', 'cmwlxjpfl0000eg5qnideikjk', 32, 98.6, 100.4, 'Gumball', 'Ah, so what? Put it with the others.', '/ɑː, soʊ wʌt? pʊt ɪt wɪð ðɪ ˈʌðərz/'),
('c06f82db7e94708c73d8348c0', 'cmwlxjpfl0000eg5qnideikjk', 33, 101, 103.8, 'Darwin', 'No, this one''s red! It means urgent!', '/noʊ, ðɪs wʌnz rɛd! ɪt miːnz ˈɜːrdʒənt!/'),
('c608a49fbec1dd47d74b8471b', 'cmwlxjpfl0000eg5qnideikjk', 34, 104.1, 105.7, 'Gumball', 'Red envelope or red writing?', '/rɛd ˈɛnvəˌloʊp ɔːr rɛd ˈraɪtɪŋ?/'),
('c0504097b00b4cd2caddd8e07', 'cmwlxjpfl0000eg5qnideikjk', 35, 106.3, 108.3, 'Darwin', 'Red writing on red envelope.', '/rɛd ˈraɪtɪŋ ɑːn rɛd ˈɛnvəˌloʊp/'),
('cbd85ed87152f6bb34dc84b06', 'cmwlxjpfl0000eg5qnideikjk', 36, 108.5, 110.6, 'Darwin', 'It''s really hard to read, actually.', '/ɪts ˈrɪəli hɑːrd tə riːd, ˈæktʃuəli/'),
('c41e47b56749a2bdf64be9949', 'cmwlxjpfl0000eg5qnideikjk', 37, 111.4, 114.7, 'Darwin', 'It says we have to pay 25 dollars for the DVD!', '/ɪt sɛz wiː hæv tə peɪ ˈtwɛnti faɪv ˈdɑːlərz fər ðə ˌdiːˌviːˈdiː!/'),
('c8c6c39eccdd8a643899c38ac', 'cmwlxjpfl0000eg5qnideikjk', 38, 115.3, 116.7, 'Gumball', 'What are we going to do?!', '/wʌt ɑːr wiː ˈɡoʊɪŋ tə duː?!/'),
('c43d3eb6bbe7cc7c5d53475d0', 'cmwlxjpfl0000eg5qnideikjk', 39, 116.9, 119.2, 'Darwin', 'Face the consequences of our actions and tell Mom?', '/feɪs ðə ˈkɑːnsəˌkwɛnsɪz əv ɑːr ˈækʃənz ənd tɛl mɑːm?/'),
('c722f5b3c248269006059dda6', 'cmwlxjpfl0000eg5qnideikjk', 40, 119.3, 122.3, 'Gumball', 'No, no, no, no, no. Just give me a little time to think.', '/noʊ, noʊ, noʊ, noʊ, noʊ. dʒʌst ɡɪv miː ə ˈlɪtəl taɪm tə θɪŋk/'),
('c199933ec1aa7b855d7b0e09b', 'cmwlxjpfl0000eg5qnideikjk', 41, 130.8, 131.7, 'Gumball', 'Huh?', '/hʌ?/'),
('cc9d4950323bb8c05ff3fdd2a', 'cmwlxjpfl0000eg5qnideikjk', 42, 131.8, 134.1, 'Darwin', 'Oh, man! More letters from Laser Video!', '/oʊ, mæn! mɔːr ˈlɛtərz frəm ˈleɪzər ˈvɪdioʊ!/'),
('c16eaee2bb77730b0290a60f4', 'cmwlxjpfl0000eg5qnideikjk', 43, 134.3, 136.4, 'Darwin', 'Oh, we are in so much trouble!', '/oʊ, wiː ɑːr ɪn soʊ mʌtʃ ˈtrʌbəl!/'),
('c0f8ebe9af9839755158cffd0', 'cmwlxjpfl0000eg5qnideikjk', 44, 136.6, 138.8, 'Darwin', 'We have to hide these before Mom gets home!', '/wiː hæv tə haɪd ðiːz bɪˈfɔːr mɑːm ɡɛts hoʊm!/'),
('c71e87409e6cef46b8116b2a7', 'cmwlxjpfl0000eg5qnideikjk', 45, 141.2, 142.1, 'Gumball', 'Yes?', '/jɛs?/'),
('ca4f717f833f0d4499939ea15', 'cmwlxjpfl0000eg5qnideikjk', 46, 142.3, 146.4, 'Nicole', 'Honey, are you in trouble? Because my mother senses are tingling. I can smell trouble.', '/ˈhʌni, ɑːr juː ɪn ˈtrʌbəl? bɪˈkəz maɪ ˈmʌðər ˈsɛnsɪz ɑːr ˈtɪŋɡlɪŋ. aɪ kən smɛl ˈtrʌbəl/'),
('c4f91c23aef7bd94ad777672a', 'cmwlxjpfl0000eg5qnideikjk', 47, 146.6, 149.2, 'Gumball', 'Trouble? No, we''re fine, absolutely fine, no trouble here, bye!', '/ˈtrʌbəl? noʊ, wɪr faɪn, ˈæbsəˌluːtli faɪn, noʊ ˈtrʌbəl hɪr, baɪ!/'),
('cd7c5056f262d563b3e2f7b28', 'cmwlxjpfl0000eg5qnideikjk', 48, 149.3, 150.3, 'Nicole', 'Are you lying?', '/ɑːr juː ˈlaɪɪŋ?/'),
('c5dd26bd24cd7fdde36ed3249', 'cmwlxjpfl0000eg5qnideikjk', 49, 150.7, 152.1, 'Gumball', 'Oh, no, of course not!', '/oʊ, noʊ, əv kɔːrs nɑːt!/'),
('cc7eb161f9b16faec90613c31', 'cmwlxjpfl0000eg5qnideikjk', 50, 152.4, 154.5, 'Nicole', 'Right, you''re lying. I''m coming home now.', '/raɪt, jʊr ˈlaɪɪŋ. aɪm ˈkʌmɪŋ hoʊm naʊ/'),
('c67fca0edfac4f85970dd30c0', 'cmwlxjpfl0000eg5qnideikjk', 51, 156.4, 158.5, 'Gumball', 'Mom''s on her way home. Now.', '/mɑːmz ɑːn hɜːr weɪ hoʊm. naʊ/'),
('c954921ead1badb86e808a721', 'cmwlxjpfl0000eg5qnideikjk', 52, 171.1, 172.5, 'Nicole', 'I knew it!', '/aɪ nuː ɪt!/'),
('c2b5684685124c70dff386aac', 'cmwlxjpfl0000eg5qnideikjk', 53, 172.7, 175.7, 'Nicole', 'You are in so much trouble!', '/juː ɑːr ɪn soʊ mʌtʃ ˈtrʌbəl!/'),
('cc8788b45291726fe435b4db2', 'cmwlxjpfl0000eg5qnideikjk', 54, 176, 178.6, 'Gumball', 'We need to get to Laser Video before Mom kicks our butt!', '/wiː niːd tə ɡɛt tə ˈleɪzər ˈvɪdioʊ bɪˈfɔːr mɑːm kɪks ɑːr bʌt!/'),
('ce0d6c8c99242f581ddec620d', 'cmwlxjpfl0000eg5qnideikjk', 55, 178.7, 181.2, 'Darwin', 'Stop the letters! Stop the letters!', '/stɑːp ðə ˈlɛtərz! stɑːp ðə ˈlɛtərz!/'),
('cfcd0d2be4b088921841ca039', 'cmwlxjpfl0000eg5qnideikjk', 56, 182.4, 185.7, 'Larry', 'Ah, the Watersons. It''s about time you showed up.', '/ɑː, ðə ˈwɔːtərsənz. ɪts əˈbaʊt taɪm juː ʃoʊd ʌp/'),
('cfd9a128ce7aa77b5ec021e22', 'cmwlxjpfl0000eg5qnideikjk', 57, 185.9, 187.6, 'Larry', 'I assume you have my money?', '/aɪ əˈsuːm juː hæv maɪ ˈmʌni?/'),
('cb4938ffa04078055acd37f94', 'cmwlxjpfl0000eg5qnideikjk', 58, 187.7, 190.8, 'Gumball', 'Better than that, ey, Larry? We got the DVD.', '/ˈbɛtər ðən ðæt, eɪ, ˈlæri? wiː ɡɑːt ðə ˌdiːˌviːˈdiː/'),
('c1f5230fceb014732a20a51db', 'cmwlxjpfl0000eg5qnideikjk', 59, 191, 195.1, 'Larry', 'I hope you don''t mind if I make sure it''s real. Last time it was a piece of cardboard.', '/aɪ hoʊp juː doʊnt maɪnd ɪf aɪ meɪk ʃʊr ɪts ˈriːəl. læst taɪm ɪt wʌz ə piːs əv ˈkɑːrdˌbɔːrd/'),
('ce33bb41e233b98046e03ca5f', 'cmwlxjpfl0000eg5qnideikjk', 60, 195.4, 196.7, 'Gumball', 'Go for it.', '/ɡoʊ fər ɪt/'),
('c955dbd210db40fe4f7e36a02', 'cmwlxjpfl0000eg5qnideikjk', 61, 201.8, 203.4, 'Narrator', 'Alligators on a Train.', '/ˈælɪˌɡeɪtərz ɑːn ə treɪn/'),
('c7d61f8a4843335a024126818', 'cmwlxjpfl0000eg5qnideikjk', 62, 204, 206.9, 'Movie Actor', 'Oh, no! There''s alligators on this train!', '/oʊ, noʊ! ðɛrz ˈælɪˌɡeɪtərz ɑːn ðɪs treɪn!/'),
('c60bb1c832ab8a75bb02d1cd2', 'cmwlxjpfl0000eg5qnideikjk', 63, 209.8, 212.8, 'Movie Actor', 'Thank goodness we got all the alligators off this train.', '/θæŋk ˈɡʊdnəs wiː ɡɑːt ɔːl ði ˈælɪˌɡeɪtərz ɔːf ðɪs treɪn/'),
('c1c59b34e4b31c637a74bf90c', 'cmwlxjpfl0000eg5qnideikjk', 64, 213, 216.4, 'Movie Actor', 'Thank you so much for saving us from all the alligators on this train.', '/θæŋk juː soʊ mʌtʃ fər ˈseɪvɪŋ ʌs frəm ɔːl ði ˈælɪˌɡeɪtərz ɑːn ðɪs treɪn/'),
('cf82e8443e681974eb405d84b', 'cmwlxjpfl0000eg5qnideikjk', 65, 220.5, 222.7, 'Movie Singer', 'Alligators off this train.', '/ˈælɪˌɡeɪtərz ɔːf ðɪs treɪn/'),
('c45b8add7190cf2497e0434b6', 'cmwlxjpfl0000eg5qnideikjk', 66, 224.5, 226.7, 'Movie Singer', 'Alligators off this train.', '/ˈælɪˌɡeɪtərz ɔːf ðɪs treɪn/'),
('c286b7f078847a6148486caeb', 'cmwlxjpfl0000eg5qnideikjk', 67, 235.8, 237.9, 'Movie Singer', 'Alligators on a train!', '/ˈælɪˌɡeɪtərz ɑːn ə treɪn!/'),
('c50e8c3accbd6c05e1a0ec35f', 'cmwlxjpfl0000eg5qnideikjk', 68, 239, 240.2, 'Larry', 'This had better be a joke.', '/ðɪs həd ˈbɛtər biː ə dʒoʊk/'),
('c3f512956b3bfed8133cdfd1e', 'cmwlxjpfl0000eg5qnideikjk', 69, 240.3, 242, 'Gumball', 'Aw, man! What gave it away?', '/ɔː, mæn! wʌt ɡeɪv ɪt əˈweɪ?/'),
('cbc9e4fa1fb429c4e6b503450', 'cmwlxjpfl0000eg5qnideikjk', 70, 242.1, 245.5, 'Larry', 'Dude, it''s 5 seconds long and every name in the credits is one of you two.', '/duːd, ɪts faɪv ˈsɛkəndz lɔːŋ ənd ˈɛvri neɪm ɪn ðə ˈkrɛdɪts ɪz wʌn əv juː tuː/'),
('c73998fe7d3fdf2ebf18cb826', 'cmwlxjpfl0000eg5qnideikjk', 71, 245.6, 247.9, 'Darwin', 'I told you we should have put some other people on the credits!', '/aɪ toʊld juː wiː ʃʊd həv pʊt səm ˈʌðər ˈpiːpəl ɑːn ðə ˈkrɛdɪts!/'),
('cdf9151a59696361608720b32', 'cmwlxjpfl0000eg5qnideikjk', 72, 248, 249.7, 'Gumball', 'What, and let them have all the glory?', '/wʌt, ənd lɛt ðɛm hæv ɔːl ðə ˈɡlɔːri?/'),
('c17a7aecd6c47012dbcc63461', 'cmwlxjpfl0000eg5qnideikjk', 73, 249.8, 253.2, 'Larry', 'Well, there''s no way I can accept this. You need to give me the real DVD now!', '/wɛl, ðɛrz noʊ weɪ aɪ kən əkˈsɛpt ðɪs. juː niːd tə ɡɪv miː ðə ˈriːəl ˌdiːˌviːˈdiː naʊ!/'),
('cbf59bc0a4ef6f56ad7e3ce6d', 'cmwlxjpfl0000eg5qnideikjk', 74, 254.2, 263.1, 'Gumball & Darwin', 'We can''t! We used it to cut a pizza, and then we scratched it with the wrong side of the scrubby sponge, and then we threw it in the waste disposal. Please don''t tell our mom!', '/wiː kænt! wiː juːzd ɪt tə kʌt ə ˈpiːtsə, ənd ðɛn wiː skrætʃt ɪt wɪð ðə rɔːŋ saɪd əv ðə ˈskrʌbi spʌndʒ, ənd ðɛn wiː θruː ɪt ɪn ðə weɪst dɪˈspoʊzəl. pliːz doʊnt tɛl ɑːr mɑːm!/'),
('cae750adf2bcefa5f092f5a7b', 'cmwlxjpfl0000eg5qnideikjk', 75, 263.3, 264.4, 'Nicole', 'I already know.', '/aɪ ɔːlˈrɛdi noʊ/'),
('c068fce95248d853371d91df8', 'cmwlxjpfl0000eg5qnideikjk', 76, 264.5, 265.4, 'Gumball & Darwin', 'Mom!', '/mɑːm!/'),
('cbfc8a86a023b082ce1e5592e', 'cmwlxjpfl0000eg5qnideikjk', 77, 265.6, 267.3, 'Nicole', 'How much is the DVD, Larry?', '/haʊ mʌtʃ ɪz ðə ˌdiːˌviːˈdiː, ˈlæri?/'),
('cb60222e57e2d708e02bb929d', 'cmwlxjpfl0000eg5qnideikjk', 78, 267.4, 268.3, 'Larry', '25 dollars.', '/ˈtwɛnti faɪv ˈdɑːlərz/'),
('ce05b0ee7e9bc72af88847f43', 'cmwlxjpfl0000eg5qnideikjk', 79, 268.5, 273.6, 'Nicole', 'What?! You made me leave work and chase you through the neighborhood on a dog for 25 dollars?!', '/wʌt?! juː meɪd miː liːv wɜːrk ənd tʃeɪs juː θruː ðə ˈneɪbərˌhʊd ɑːn ə dɔːɡ fər ˈtwɛnti faɪv ˈdɑːlərz?!/'),
('ce4149fc0fac8f5dcbca8139f', 'cmwlxjpfl0000eg5qnideikjk', 80, 274.2, 275.9, 'Gumball', 'But we were scared to tell you.', '/bət wiː wər skɛrd tə tɛl juː/'),
('c5384d209abaf0912612e8920', 'cmwlxjpfl0000eg5qnideikjk', 81, 276.5, 281.3, 'Nicole', 'Aw, silly. There''s nothing you can do that will ever stop me loving you. Come here.', '/ɔː, ˈsɪli. ðɛrz ˈnʌθɪŋ juː kən duː ðæt wɪl ˈɛvər stɑːp miː ˈlʌvɪŋ juː. kʌm hɪr/'),
('c4b6fd064fbd4339d4f7c70f2', 'cmwlxjpfl0000eg5qnideikjk', 82, 284.1, 285.8, 'Nicole', 'Now let me pay for that.', '/naʊ lɛt miː peɪ fər ðæt/'),
('c3571fe21addf44df5312a681', 'cmwlxjpfl0000eg5qnideikjk', 83, 286, 290.3, 'Gumball', 'See, Darwin? You should always tell the truth and face the consequences of your actions.', '/siː, ˈdɑːrwɪn? juː ʃʊd ˈɔːlweɪz tɛl ðə truːθ ənd feɪs ðə ˈkɑːnsəˌkwɛnsɪz əv jɔːr ˈækʃənz/'),
('c9cac333733887ff88e501cbb', 'cmwlxjpfl0000eg5qnideikjk', 84, 291.5, 292.5, 'Gumball', 'Ow!', '/aʊ!/');
